    curve(g,v,function(x){ var cc=Math.pow(10,-x), h=(cc+Math.sqrt(cc*cc+4*KW))/2; return p.kind==='acid'?-Math.log10(h):14+Math.log10(h); },C.fry,3);
    curve(g,v,function(x){ return p.kind==='acid'?x:14-x; },TH.dim,1.5,[5,5]); H.seg(g,v.sx(7),gr.t,v.sx(7),gr.t+gr.h,C.cyan,1,[3,4]);
