    var fb=wide?{l:6,t:6,w:W*0.3,h:Hh-12}:{l:6,t:6,w:W-12,h:Hh*0.3}, gr=wide?{l:fb.w+56,t:20,w:W-fb.w-78,h:Hh-62}:{l:50,t:fb.h+26,w:W-66,h:Hh-fb.h-66};
