/* ===================== 7. 표지 재포획법 (고1 생태계와 환경, 고3 개체군) ===================== */
(function(){
var S={dots:[],M:0,R:null,n:0,est:[],caught:{},rng:null};
function mk(N){ var d=[]; for(var i=0;i<N;i++) d.push({x:Math.random(),y:Math.random(),m:false}); return d; }
function shuffle(a){ for(var i=a.length-1;i>0;i--){ var j=Math.floor(Math.random()*(i+1)), t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function marked(){ var c=0; S.dots.forEach(function(d){ if(d.m) c++; }); return c; }
var E={id:'s2_mark', cat:CAT, icon:'🐟', name:'표지 재포획법으로 개체 수 세기', desc:'연못 속 물고기를 모두 세지 않고 개체 수를 어림해요',
  info:'움직이는 동물은 전부 세기 어려워서 표지 재포획법을 써요. 먼저 M마리를 잡아 표지를 붙여 놓아주고, 충분히 섞인 뒤 n마리를 다시 잡아 표지된 개체가 R마리라면, 표지 비율이 전체에서도 같다고 보고 전체 개체 수 N ≈ M × n ÷ R로 어림해요(린컨-피터슨 추정). 표지된 개체가 고르게 섞이고 표지가 떨어지지 않으며 개체 수가 변하지 않아야 믿을 수 있어요.',
  tries:['먼저 표지하기를 누르고 다시 잡기를 여러 번 눌러 추정값이 얼마나 흔들리는지 보세요','다시 잡는 마릿수 n을 10에서 100으로 늘리면 추정값의 흔들림이 어떻게 되나요?','표지한 마릿수 M이 너무 적을 때 R이 0이 되면 어떻게 되나요?'],
  hint:'1. 표지하고 놓아주기 → 2. 다시 잡기를 여러 번 눌러 보세요.', noPlay:true,
  params:[P('N','연못의 실제 개체 수 (숨겨진 값)',50,1000,10,300,'마리',null,{d:0}),P('M','표지해서 놓아주는 수 M',5,200,5,50,'마리',null,{d:0}),P('n','다시 잡는 수 n',5,200,5,50,'마리',null,{d:0})],
  cols:[{k:'N',l:'실제 개체 수',d:0},{k:'M',l:'표지한 수 M',d:0},{k:'n',l:'다시 잡은 수 n',d:0},{k:'R',l:'표지된 개체 수 R',d:0},{k:'est',l:'추정한 개체 수',d:0}], gx:'N', gy:'est', fit:true,
  fitHint:function(m,b,x,y){ if(x==='N'&&y==='est') return F('기울기가 1에 가까울수록 추정이 정확해요 (지금 {0})',fmt(m,2)); },
  actions:[['mark','표지하고 놓아주기'],['catch','다시 잡기']],
  act:function(a){ var p=this.p; if(a==='mark'){ S.dots.forEach(function(d){ d.m=false; }); var idx=shuffle(S.dots.map(function(d,i){ return i; })).slice(0,Math.min(p.M,S.dots.length)); idx.forEach(function(i){ S.dots[i].m=true; }); S.M=idx.length; S.R=null; S.caught={}; S.dots.forEach(function(d){ d.x=Math.random(); d.y=Math.random(); }); }
    else { if(!S.M){ H.toast(T('먼저 표지하고 놓아주기를 눌러 주세요')); return; } S.dots.forEach(function(d){ d.x=Math.random(); d.y=Math.random(); }); var idx2=shuffle(S.dots.map(function(d,i){ return i; })).slice(0,Math.min(p.n,S.dots.length)); S.caught={}; var R=0; idx2.forEach(function(i){ S.caught[i]=1; if(S.dots[i].m) R++; }); S.R=R; S.n=idx2.length; S.est.push(R>0?S.M*S.n/R:null); if(S.est.length>200) S.est.shift(); } },
  reset:function(){ S.dots=mk(this.p.N); S.M=0; S.R=null; S.n=0; S.est=[]; S.caught={}; },
  change:function(k){ if(k==='N'||k==='M') this.reset(); },
  last:function(){ var e=S.est; return e.length?e[e.length-1]:null; },
  mean:function(){ var a=S.est.filter(function(x){ return x!=null; }); return a.length?a.reduce(function(s,x){ return s+x; },0)/a.length:null; },
  draw:function(g,W,Hh){ var p=this.p, r=R4(W,Hh,10), pond={l:r.l,t:r.t,w:r.w,h:Math.max(60,r.h*0.62)}, cx=pond.l+pond.w/2, cy=pond.t+pond.h/2;
    g.beginPath(); g.ellipse(cx,cy,pond.w/2,pond.h/2,0,0,TAU); g.fillStyle=TH.light?'#cfe6fa':'#10304f'; g.fill(); g.strokeStyle=C.blu; g.lineWidth=2; g.stroke();
    var any=false; for(var k in S.caught){ any=true; break; }
    S.dots.forEach(function(d,i){ var a=d.x*TAU, rr=Math.sqrt(d.y), x=cx+Math.cos(a)*rr*(pond.w/2-10), y=cy+Math.sin(a)*rr*(pond.h/2-10), c=S.caught[i];
      if(c){ g.beginPath(); g.arc(x,y,7,0,TAU); g.strokeStyle=C.fry; g.lineWidth=2.5; g.stroke(); }
      H.dot(g,x,y,3.2,d.m?C.red:(TH.light?'#2a6fae':'#9fd2ff')); });
    var by=pond.t+pond.h+14; var L=this.last(), mu=this.mean(); var lines=[[F('표지한 수 M = {0}',S.M),C.red],[any?F('다시 잡은 수 n = {0}, 표지된 개체 R = {1}',S.n,S.R):T('아직 다시 잡지 않았어요'),C.fry],[L!=null?F('N ≈ M × n ÷ R = {0}',num(L,0)):(any?T('R = 0이라 추정할 수 없어요'):''),C.grn]];
    lines.forEach(function(q,i){ if(q[0]) H.text(g,q[0],r.l+4,by+i*20,{size:13.5,w:700,c:q[1]}); });
    /* strip of past estimates */
    var sr={l:r.l+6,t:by+66,w:r.w-12,h:Math.max(24,r.t+r.h-by-72)}; if(S.est.length>0&&sr.h>26){ var sv=H.view(sr,0,Math.max(10,S.est.length),0,Math.max(p.N*2,10)); H.axes(g,sv,{box:true,noVGrid:true,xl:T('시도'),ys:Math.max(100,H.nice(p.N*2,2))});
      clip(g,sv,function(){ H.seg(g,sv.l,sv.sy(p.N),sv.l+sv.w,sv.sy(p.N),C.grn,1.5,[5,4]); S.est.forEach(function(q,i){ if(q!=null) H.dot(g,sv.sx(i+0.5),sv.sy(q),3.5,C.fry); }); }); } },
  read:function(){ var L=this.last(), mu=this.mean(), ns=S.est.filter(function(x){ return x!=null; }), sd=null; if(ns.length>1){ var m=mu; sd=Math.sqrt(ns.reduce(function(s,x){ return s+(x-m)*(x-m); },0)/(ns.length-1)); }
    return [RD('표지한 수 M',num(S.M,0),'마리'),RD('다시 잡은 수 n',num(S.n,0),'마리'),RD('표지된 개체 R',S.R==null?'—':num(S.R,0),'마리'),RD('이번 추정값',L==null?'—':num(L,0),'마리','hl'),RD('추정값의 평균',mu==null?'—':num(mu,0),'마리','th'),RD('추정값의 표준편차',sd==null?'—':num(sd,0),'마리'),RD('실제 개체 수',num(this.p.N,0),'마리','ok')]; },
  record:function(){ var L=this.last(); if(L==null) return '먼저 다시 잡기를 해서 추정값을 만들어 주세요'; return {N:this.p.N, M:S.M, n:S.n, R:S.R, est:L}; },
  ai:function(){ var p=this.p, L=this.last(); return 'Mark-recapture simulation: true population '+p.N+', marked M = '+S.M+', recapture n = '+S.n+', recaptured marked R = '+S.R+'. Lincoln-Petersen estimate N = M n / R = '+(L==null?'n/a':fmt(L,0))+'. Mean of '+S.est.length+' trials: '+(this.mean()==null?'n/a':fmt(this.mean(),0))+'.'; }
};
LAB.add(E);
})();

