  cols:[{k:'m1',l:'물체 1의 질량 m₁',u:'kg',d:2},{k:'m2',l:'물체 2의 질량 m₂',u:'kg',d:2},{k:'a',l:'가속도 a',u:'m/s²',d:3},{k:'t1',l:'1 m 이동하는 데 걸리는 시간',u:'s',d:2}], gx:'m2', gy:'a', join:true,
  reset:function(){ S.x=0; S.v=0; S.t=0; S.hist=[[0,0]]; }, change:function(){ this.reset(); },
