  cols:[{k:'f',l:'빛의 진동수 f',u:'×10¹⁴ Hz',d:3},{k:'V0',l:'정지 전압 V₀',u:'V',d:3},{k:'lam',l:'빛의 파장 λ',u:'nm',d:0},{k:'K',l:'최대 운동 에너지',u:'eV',d:3}], gx:'f', gy:'V0', fit:true,
