  cols:[{k:'x',l:'1/n_f² − 1/nᵢ²',d:4},{k:'inv',l:'1 ÷ λ',u:'μm⁻¹',d:4},{k:'lam',l:'빛의 파장 λ',u:'nm',d:1}], gx:'x', gy:'inv', fit:true,
  fitHint:function(m,b,x,y){ if(x==='x'&&y==='inv') return F('기울기 {0} μm⁻¹ = 뤼드베리 상수 R ≈ {1} × 10⁷ m⁻¹',fmt(m,3),fmt(m/10,4)); },
