    if(!c.none){ var xm=ed.l+ed.w*0.55, ya=ey(p.ni), yb=ey(p.nf), col=c.lam>=380&&c.lam<=780?rgb(wl2rgb(c.lam)):'#b8a2ff'; H.arrow(g,xm,ya,xm,yb,col,3.5,12);
      var px=xm+22, py=(ya+yb)/2; g.beginPath(); for(var s=0;s<=30;s++){ var xx=px+s*3, yy=py+Math.sin(s*0.9)*7; if(s) g.lineTo(xx,yy); else g.moveTo(xx,yy); } g.strokeStyle=col; g.lineWidth=2.5; g.stroke(); H.text(g,num(c.lam,1)+' nm',px+46,py-16,{size:13,w:800,c:col}); lab(g,c.emit?'방출':'흡수',px+46,py+20,TH.dim,'left',12); }
