  cols:[{k:'B',l:'자기장의 세기 B',u:'mT',d:1},{k:'invB',l:'1 ÷ B',u:'mT⁻¹',d:3},{k:'v',l:'입자의 속력 v',u:'×10⁶ m/s',d:1},{k:'r',l:'원 궤도의 반지름 r',u:'m',d:4}], gx:'invB', gy:'r', fit:true,
  fitHint:function(m,b,x,y){ if(x==='invB'&&y==='r'&&m>0){ var q=Math.abs(PT[this.p.pt][2]); return F('기울기 {0} = mv/q → 질량 m ≈ {1} kg',sci(m*1e-3,2),sci(m*1e-3*q/(this.p.v*1e6),2)); } },
