    clip(g,v,function(){ g.fillStyle='rgba(63,224,143,.14)'; g.fillRect(v.l,v.sy(p.pKa+1),v.w,v.sy(p.pKa-1)-v.sy(p.pKa+1)); }); lab(g,'완충 구간 (pH = pKa ± 1)',gr.l+gr.w-6,v.sy(p.pKa+1)-8,C.grn,'right',11.5);
    var pts=[], pts2=[]; for(var i=0;i<=240;i++){ var x=ve*2*i/240; pts.push([v.sx(x),v.sy(ph(p,x))]); pts2.push([v.sx(x),v.sy(phStrong(p,x))]); } H.line(g,pts2,TH.dim,1.6,[5,5]); H.line(g,pts,C.fry,3);
